// The published-documentation manifest, and the gate that keeps it current.
//
// A `slug` in a markdown file's frontmatter is what publishes it to leapsake.com,
// from anywhere in the repository (apps/website/src/lib/docs.ts). That buys
// co-location — a guide can sit beside the code it describes — and costs the one
// thing a `docs/` directory would have given for free: you can no longer see the
// published set without opening files.
//
// `apps/website/docs-manifest.json` buys it back. It maps every public URL to the
// file that claims it, it is committed, and it is regenerated by the site build — so
// a changed *public URL* appears in a pull request diff rather than only in a deploy.
//
//   node scripts/docs-manifest.mjs          regenerate it
//   node scripts/docs-manifest.mjs --check  fail if it is stale (the `test:docs` tier)
//
// Same guard as `test:versions` and `test:icons`, for the same reason: without it the
// failure is invisible until it ships. Unlike those two, what it protects is a URL —
// and a URL that moves silently breaks every link already pointing at it.
import { spawnSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const WEBSITE = join(ROOT, "apps", "website");
const MANIFEST = join(WEBSITE, "docs-manifest.json");

const read = () => {
  try {
    return readFileSync(MANIFEST, "utf8");
  } catch {
    return undefined;
  }
};

/** `astro sync` runs the content layer, which is what writes the manifest. */
function regenerate() {
  const { status, stderr } = spawnSync("pnpm", ["exec", "astro", "sync"], {
    cwd: WEBSITE,
    encoding: "utf8",
    stdio: ["ignore", "ignore", "pipe"],
  });
  if (status !== 0) {
    console.error("✗ could not read the documentation set\n");
    console.error(stderr.trim());
    process.exit(1);
  }
}

const before = read();
regenerate();
const after = read();

if (process.argv[2] !== "--check") {
  const count = Object.keys(JSON.parse(after ?? "{}")).length;
  console.log(
    `✓ docs-manifest.json regenerated — ${count} published document(s)`,
  );
  process.exit(0);
}

if (before === after) {
  const count = Object.keys(JSON.parse(after ?? "{}")).length;
  console.log(
    `✓ docs-manifest.json is current — ${count} published document(s)`,
  );
  process.exit(0);
}

// Leave the tree as it was found: a check tier reports, it does not edit.
if (before !== undefined) writeFileSync(MANIFEST, before);

const slugs = (json) => new Set(Object.keys(JSON.parse(json ?? "{}")));
const was = slugs(before);
const now = slugs(after);

console.error("✗ docs-manifest.json is stale\n");
for (const slug of now) if (!was.has(slug)) console.error(`  + ${slug}`);
for (const slug of was) if (!now.has(slug)) console.error(`  - ${slug}`);
console.error(
  "\nEach line is a public URL appearing or disappearing. If that is intended, run:" +
    "\n  node scripts/docs-manifest.mjs   (then commit the manifest)",
);
process.exit(1);
